def outcome(text: str) -> str:
    result = jenkins.analyze("Jenkinsfile", text.encode(), CATALOG, None)
    if any(f.rule == "OBAAF-JEN-005" for f in result.findings):
        return "finding"
    if any(u.rule == "OBAAF-JEN-005" and "independent" not in u.reason for u in result.unknowns):
        return "unknown"
    return "quiet"


CATALOG = load()


class ApprovalBypassTests(unittest.TestCase):
    def test_every_attempt(self):
        for case, _before, expected, text in CASES:
            with self.subTest(case=case):
                self.assertEqual(outcome(text), expected)

    def test_limits_are_cases(self):
        self.assertLessEqual(set(LIMITS), {c[0] for c in CASES})

    def test_every_way_past_is_now_reported(self):
        # Quiet before the slice and a finding or cannot tell now: the ways past the slice fixed.
        fixed = {c[0] for c in CASES if c[1] == "quiet" and c[2] != "quiet"}
        self.assertGreaterEqual(len(fixed), 45)

if __name__ == "__main__":
    unittest.main()
